pub const PY1452_SCC_KOSARAJU: CodingStep = CodingStep {
    id: "py-1452-scc-kosaraju", title: "SCC · Kosaraju", objective: "Calcular componentes fuertemente conexas con Kosaraju.",
    prompt_md: "**Kosaraju**\n\nKosaraju hace dos DFS: uno sobre el grafo y otro sobre el transpuesto, en orden inverso de finalización.\n\n**Micro-reto:**\n1. Definí `kosaraju(ady)` que devuelva la lista de componentes (listas ordenadas)\n2. Aplicala a `{0:[1],1:[0,2],2:[],3:[4],4:[3]}`\n3. Imprimí las componentes",
    starter_code: "# def kosaraju(ady):\n#     visitados = set()\n#     orden = []\n#     def visitar(nodo):\n#         visitados.add(nodo)\n#         for vecino in ady.get(nodo, []):\n#             if vecino not in visitados:\n#                 visitar(vecino)\n#         orden.append(nodo)\n#     for nodo in ady:\n#         if nodo not in visitados:\n#             visitar(nodo)\n#     transp = {nodo: [] for nodo in ady}\n#     for u in ady:\n#         for v in ady[u]:\n#             transp[v].append(u)\n#     componentes = []\n#     visitados2 = set()\n#     for nodo in reversed(orden):\n#         if nodo not in visitados2:\n#             componente = []\n#             pila = [nodo]\n#             visitados2.add(nodo)\n#             while pila:\n#                 u = pila.pop()\n#                 componente.append(u)\n#                 for v in transp[u]:\n#                     if v not in visitados2:\n#                         visitados2.add(v)\n#                         pila.append(v)\n#             componentes.append(sorted(componente))\n#     return sorted(componentes)\n# resultado = kosaraju({0: [1], 1: [0, 2], 2: [], 3: [4], 4: [3]})\n# print(resultado)\n",
    pytest: "def test_scc_kosaraju(capsys):\n    ns = {}\n    exec(open('solution.py', encoding='utf-8').read(), ns)\n    assert ns['resultado'] == [[0, 1], [2], [3, 4]]\n    assert ns['kosaraju']({0: [1], 1: [0]}) == [[0, 1]]\n    assert capsys.readouterr().out.strip() == str([[0, 1], [2], [3, 4]])\n",
    hint: "DFS en el transpuesto en orden inverso de finish.",
    solution_example: "def kosaraju(ady):\n    visitados = set()\n    orden = []\n    def visitar(nodo):\n        visitados.add(nodo)\n        for vecino in ady.get(nodo, []):\n            if vecino not in visitados:\n                visitar(vecino)\n        orden.append(nodo)\n    for nodo in ady:\n        if nodo not in visitados:\n            visitar(nodo)\n    transp = {nodo: [] for nodo in ady}\n    for u in ady:\n        for v in ady[u]:\n            transp[v].append(u)\n    componentes = []\n    visitados2 = set()\n    for nodo in reversed(orden):\n        if nodo not in visitados2:\n            componente = []\n            pila = [nodo]\n            visitados2.add(nodo)\n            while pila:\n                u = pila.pop()\n                componente.append(u)\n                for v in transp[u]:\n                    if v not in visitados2:\n                        visitados2.add(v)\n                        pila.append(v)\n            componentes.append(sorted(componente))\n    return sorted(componentes)\n\nresultado = kosaraju({0: [1], 1: [0, 2], 2: [], 3: [4], 4: [3]})\nprint(resultado)\n",
    next: Some("py-1453-scc-tarjan"), show_type_chips: false, micro_step: 1452,
};
pub const PY1453_SCC_TARJAN: CodingStep = CodingStep {
    id: "py-1453-scc-tarjan", title: "SCC · Tarjan", objective: "Calcular componentes fuertemente conexas con Tarjan.",
    prompt_md: "**Tarjan**\n\nTarjan halla SCCs en un solo DFS usando índices y valores `low` para detectar raíces de componentes.\n\n**Micro-reto:**\n1. Definí `tarjan(ady)` que devuelva las componentes ordenadas\n2. Aplicala a `{0:[1],1:[0,2],2:[],3:[4],4:[3]}`\n3. Imprimí las componentes",
    starter_code: "# def tarjan(ady):\n#     index = {}\n#     low = {}\n#     pila = []\n#     en_pila = set()\n#     contador = [0]\n#     componentes = []\n#     def fuerte(nodo):\n#         index[nodo] = low[nodo] = contador[0]\n#         contador[0] += 1\n#         pila.append(nodo)\n#         en_pila.add(nodo)\n#         for vecino in ady.get(nodo, []):\n#             if vecino not in index:\n#                 fuerte(vecino)\n#                 low[nodo] = min(low[nodo], low[vecino])\n#             elif vecino in en_pila:\n#                 low[nodo] = min(low[nodo], index[vecino])\n#         if low[nodo] == index[nodo]:\n#             componente = []\n#             while True:\n#                 w = pila.pop()\n#                 en_pila.remove(w)\n#                 componente.append(w)\n#                 if w == nodo:\n#                     break\n#             componentes.append(sorted(componente))\n#     for nodo in ady:\n#         if nodo not in index:\n#             fuerte(nodo)\n#     return sorted(componentes)\n# resultado = tarjan({0: [1], 1: [0, 2], 2: [], 3: [4], 4: [3]})\n# print(resultado)\n",
    pytest: "def test_scc_tarjan(capsys):\n    ns = {}\n    exec(open('solution.py', encoding='utf-8').read(), ns)\n    assert ns['resultado'] == [[0, 1], [2], [3, 4]]\n    assert ns['tarjan']({0: [1], 1: [0]}) == [[0, 1]]\n    assert capsys.readouterr().out.strip() == str([[0, 1], [2], [3, 4]])\n",
    hint: "low == index marca la raíz de una SCC.",
    solution_example: "def tarjan(ady):\n    index = {}\n    low = {}\n    pila = []\n    en_pila = set()\n    contador = [0]\n    componentes = []\n    def fuerte(nodo):\n        index[nodo] = low[nodo] = contador[0]\n        contador[0] += 1\n        pila.append(nodo)\n        en_pila.add(nodo)\n        for vecino in ady.get(nodo, []):\n            if vecino not in index:\n                fuerte(vecino)\n                low[nodo] = min(low[nodo], low[vecino])\n            elif vecino in en_pila:\n                low[nodo] = min(low[nodo], index[vecino])\n        if low[nodo] == index[nodo]:\n            componente = []\n            while True:\n                w = pila.pop()\n                en_pila.remove(w)\n                componente.append(w)\n                if w == nodo:\n                    break\n            componentes.append(sorted(componente))\n    for nodo in ady:\n        if nodo not in index:\n            fuerte(nodo)\n    return sorted(componentes)\n\nresultado = tarjan({0: [1], 1: [0, 2], 2: [], 3: [4], 4: [3]})\nprint(resultado)\n",
    next: Some("py-1454-scc-count"), show_type_chips: false, micro_step: 1453,
};
