pub const PY1480_PROJECT_ASSEMBLE: CodingStep = CodingStep {
    id: "py-1480-project-assemble", title: "Proyecto · Ensamblar pipeline", objective: "Integrar modelado, rutas, flujo y componentes en un pipeline.",
    prompt_md: "**Proyecto: ensamblar pipeline**\n\nIntegrá todo: modelar la red, hallar la ruta más corta, el cuello de botella y contar componentes.\n\n**Micro-reto:**\n1. Definí las funciones auxiliares y `pipeline_red(aristas, fuente, sumidero)`\n2. Devolvé un dict con `ruta`, `distancia`, `flujo` y `componentes`\n3. Imprimí el dict de `pipeline_red([(0,1,5),(0,2,2),(1,3,3),(2,3,4)], 0, 3)`",
    starter_code: "# import heapq\n# def modelar_red(aristas):\n#     ady = {}\n#     for a, b, peso in aristas:\n#         ady.setdefault(a, []).append((b, peso))\n#         ady.setdefault(b, []).append((a, peso))\n#     return ady\n# def ruta_mas_corta(ady, inicio, destino):\n#     dist = {inicio: 0}\n#     prev = {}\n#     heap = [(0, inicio)]\n#     while heap:\n#         d, nodo = heapq.heappop(heap)\n#         if d > dist.get(nodo, float('inf')):\n#             continue\n#         for vecino, peso in ady.get(nodo, []):\n#             nueva = d + peso\n#             if nueva < dist.get(vecino, float('inf')):\n#                 dist[vecino] = nueva\n#                 prev[vecino] = nodo\n#                 heapq.heappush(heap, (nueva, vecino))\n#     camino = []\n#     nodo = destino\n#     while nodo in prev:\n#         camino.append(nodo)\n#         nodo = prev[nodo]\n#     camino.append(inicio)\n#     return dist.get(destino, float('inf')), camino[::-1]\n# def cuello_botella(ady, fuente, sumidero):\n#     residual = {}\n#     for u in ady:\n#         for v, cap in ady[u]:\n#             residual.setdefault(u, {})[v] = cap\n#     total = 0\n#     while True:\n#         visitados = {fuente}\n#         cola = [fuente]\n#         previo = {}\n#         while cola:\n#             u = cola.pop(0)\n#             for v, c in residual.get(u, {}).items():\n#                 if c > 0 and v not in visitados:\n#                     visitados.add(v)\n#                     previo[v] = u\n#                     cola.append(v)\n#         if sumidero not in visitados:\n#             break\n#         cuello = float('inf')\n#         v = sumidero\n#         while v != fuente:\n#             u = previo[v]\n#             cuello = min(cuello, residual[u][v])\n#             v = u\n#         v = sumidero\n#         while v != fuente:\n#             u = previo[v]\n#             residual[u][v] -= cuello\n#             residual.setdefault(v, {})[u] = residual.setdefault(v, {}).get(u, 0) + cuello\n#             v = u\n#         total += cuello\n#     return total\n# def componentes_conexas(ady):\n#     visitados = set()\n#     cantidad = 0\n#     for inicio in ady:\n#         if inicio in visitados:\n#             continue\n#         cantidad += 1\n#         pila = [inicio]\n#         visitados.add(inicio)\n#         while pila:\n#             nodo = pila.pop()\n#             for vecino, _ in ady[nodo]:\n#                 if vecino not in visitados:\n#                     visitados.add(vecino)\n#                     pila.append(vecino)\n#     return cantidad\n# def pipeline_red(aristas, fuente, sumidero):\n#     red = modelar_red(aristas)\n#     distancia, ruta = ruta_mas_corta(red, fuente, sumidero)\n#     flujo = cuello_botella(red, fuente, sumidero)\n#     componentes = componentes_conexas(red)\n#     return {'ruta': ruta, 'distancia': distancia, 'flujo': flujo, 'componentes': componentes}\n# resultado = pipeline_red([(0, 1, 5), (0, 2, 2), (1, 3, 3), (2, 3, 4)], 0, 3)\n# print(resultado)\n",
    pytest: "def test_project_assemble(capsys):\n    ns = {}\n    exec(open('solution.py', encoding='utf-8').read(), ns)\n    assert ns['resultado'] == {'ruta': [0, 2, 3], 'distancia': 6, 'flujo': 5, 'componentes': 1}\n    assert ns['pipeline_red']([(0, 1, 3)], 0, 1) == {'ruta': [0, 1], 'distancia': 3, 'flujo': 3, 'componentes': 1}\n    assert capsys.readouterr().out.strip() == str({'ruta': [0, 2, 3], 'distancia': 6, 'flujo': 5, 'componentes': 1})\n",
    hint: "Integrá las funciones del bloque 10.",
    solution_example: "import heapq\n\ndef modelar_red(aristas):\n    ady = {}\n    for a, b, peso in aristas:\n        ady.setdefault(a, []).append((b, peso))\n        ady.setdefault(b, []).append((a, peso))\n    return ady\n\ndef ruta_mas_corta(ady, inicio, destino):\n    dist = {inicio: 0}\n    prev = {}\n    heap = [(0, inicio)]\n    while heap:\n        d, nodo = heapq.heappop(heap)\n        if d > dist.get(nodo, float('inf')):\n            continue\n        for vecino, peso in ady.get(nodo, []):\n            nueva = d + peso\n            if nueva < dist.get(vecino, float('inf')):\n                dist[vecino] = nueva\n                prev[vecino] = nodo\n                heapq.heappush(heap, (nueva, vecino))\n    camino = []\n    nodo = destino\n    while nodo in prev:\n        camino.append(nodo)\n        nodo = prev[nodo]\n    camino.append(inicio)\n    return dist.get(destino, float('inf')), camino[::-1]\n\ndef cuello_botella(ady, fuente, sumidero):\n    residual = {}\n    for u in ady:\n        for v, cap in ady[u]:\n            residual.setdefault(u, {})[v] = cap\n    total = 0\n    while True:\n        visitados = {fuente}\n        cola = [fuente]\n        previo = {}\n        while cola:\n            u = cola.pop(0)\n            for v, c in residual.get(u, {}).items():\n                if c > 0 and v not in visitados:\n                    visitados.add(v)\n                    previo[v] = u\n                    cola.append(v)\n        if sumidero not in visitados:\n            break\n        cuello = float('inf')\n        v = sumidero\n        while v != fuente:\n            u = previo[v]\n            cuello = min(cuello, residual[u][v])\n            v = u\n        v = sumidero\n        while v != fuente:\n            u = previo[v]\n            residual[u][v] -= cuello\n            residual.setdefault(v, {})[u] = residual.setdefault(v, {}).get(u, 0) + cuello\n            v = u\n        total += cuello\n    return total\n\ndef componentes_conexas(ady):\n    visitados = set()\n    cantidad = 0\n    for inicio in ady:\n        if inicio in visitados:\n            continue\n        cantidad += 1\n        pila = [inicio]\n        visitados.add(inicio)\n        while pila:\n            nodo = pila.pop()\n            for vecino, _ in ady[nodo]:\n                if vecino not in visitados:\n                    visitados.add(vecino)\n                    pila.append(vecino)\n    return cantidad\n\ndef pipeline_red(aristas, fuente, sumidero):\n    red = modelar_red(aristas)\n    distancia, ruta = ruta_mas_corta(red, fuente, sumidero)\n    flujo = cuello_botella(red, fuente, sumidero)\n    componentes = componentes_conexas(red)\n    return {'ruta': ruta, 'distancia': distancia, 'flujo': flujo, 'componentes': componentes}\n\nresultado = pipeline_red([(0, 1, 5), (0, 2, 2), (1, 3, 3), (2, 3, 4)], 0, 3)\nprint(resultado)\n",
    next: Some("py-1481-trie-insert"), show_type_chips: false, micro_step: 1480,
};

